import { samplePDF } from './pdf-fixture.js';
import {test,expect} from '@playwright/test';
import {standaloneOnly} from './standalone-helper.js';
const account='00000000-0000-0000-0000-000000000001';
async function backend(page,role,signupError){let site=null,revision=0,works=[],passwordUpdates=0;const calls=[];
 await page.route('https://*.supabase.co/**',async route=>{const request=route.request(),url=new URL(request.url()),path=url.pathname;calls.push(path);let body={};if(request.method()==='POST'&&request.postData()&&(request.headers()['content-type']||'').includes('application/json'))body=request.postDataJSON();const user={id:account,email:role+'@example.test',user_metadata:{full_name:'Participante'}};
 const token={access_token:'test-access-token',refresh_token:'test-refresh-token',expires_in:3600};
 if(path.startsWith('/storage/v1/object/site-media/')&&request.method()==='POST')return route.fulfill({json:{Key:path.slice('/storage/v1/object/'.length)}});
 if(path.startsWith('/storage/v1/object/public/site-media/'))return route.fulfill({contentType:'image/png',body:Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+j8ioAAAAASUVORK5CYII=','base64')});
 if(path==='/rest/v1/cms_site')return route.fulfill({json:[{document:site,revision}]});
 if(path==='/auth/v1/token')return route.fulfill({json:token});
 if(path==='/auth/v1/recover')return route.fulfill({json:{}});
 if(path==='/auth/v1/verify')return route.fulfill({json:token});
 if(path==='/auth/v1/user'&&request.method()==='PUT'){passwordUpdates++;return route.fulfill({json:user});}
 if(path==='/auth/v1/user')return route.fulfill({json:user});
 if(path==='/auth/v1/signup'&&signupError)return route.fulfill({status:signupError.status,json:{code:signupError.code,msg:signupError.msg}});
 if(path==='/auth/v1/signup')return route.fulfill({json:{user}});
 if(path==='/auth/v1/logout')return route.fulfill({status:204});
 if(path==='/rest/v1/cms_admins')return route.fulfill({json:role==='visitor'?[]:[{user_id:account,owner:role==='owner',chef:role==='chef'}]});
 if(path==='/rest/v1/rpc/publish_site'){site=body.new_document;revision++;return route.fulfill({json:{revision,document:site}});}
 if(path==='/rest/v1/rpc/submit_work_with_visibility'){works.push({id:'00000000-0000-0000-0000-000000000020',author_id:account,title:body.work_title,kind:body.work_kind,summary:body.work_summary,body:body.work_body,reference_url:body.work_reference,attachment_paths:[],status:'received',feedback:'',visibility:body.work_visibility||'private',created_at:new Date().toISOString()});return route.fulfill({json:works[0].id});}
 if(path==='/rest/v1/rpc/public_works')return route.fulfill({json:works.filter(w=>w.visibility==='public').map(({feedback,status,author_id,...w})=>w)});
 if(path==='/rest/v1/rpc/set_work_visibility'){works.find(w=>w.id===body.work_id).visibility=body.work_visibility;return route.fulfill({status:204});}
 if(path==='/rest/v1/work_submissions')return route.fulfill({json:works});
 if(path==='/rest/v1/rpc/review_work'){const item=works.find(item=>item.id===body.work_id);Object.assign(item,{status:body.decision,feedback:body.message});return route.fulfill({status:204});}
 return route.fulfill({status:404,json:{message:'unexpected_test_request'}});
 });return {calls,get passwordUpdates(){return passwordUpdates;},get site(){return site;},get works(){return works;},addWork(){works.push({id:'00000000-0000-0000-0000-000000000020',title:'Investigación de maíz',kind:'research',summary:'Una propuesta sobre técnicas de fermentación.',body:'Resultados de investigación y posible desarrollo gastronómico en colaboración.',status:'received',feedback:'',attachment_paths:[],created_at:new Date().toISOString()});}};
}
async function login(page,role){await page.goto('/#cuenta');await page.getByLabel('Correo electrónico',{exact:true}).fill(role+'@example.test');await page.getByLabel('Contraseña',{exact:true}).fill('test-password-1234');await page.getByRole('button',{name:'Entrar',exact:true}).click();await expect(page.getByRole('heading',{name:role==='visitor'?'Hola, Participante.':'Tu panel de control'})).toBeVisible();}
// Controls appear only in edit mode; this turns it on once and is safe to call again.
async function editOn(page){const toggle=page.locator('[data-layout-toggle]');if(!(await toggle.waitFor({timeout:4000}).then(()=>true,()=>false)))return;const on=()=>page.evaluate(()=>document.body.classList.contains('visual-editing'));if(!(await on()))await toggle.click();await expect.poll(on).toBe(true);}
async function editOff(page){const on=()=>page.evaluate(()=>document.body.classList.contains('visual-editing'));if(await on())await page.locator('[data-layout-toggle]').click();await expect.poll(on).toBe(false);}

// Free positioning is an advanced option inside the move dialog; open it before using it.
async function openAdvanced(modal){const details=modal.locator('details.advanced-move');if(await details.getAttribute('open')===null)await details.locator('summary').click();return modal;}

// Advanced tool buttons (lock, arrows, center, scale) sit behind the "⋯" button.
async function expandTool(page){const more=page.locator('.layout-float-tools .tool-more:visible').first();if(await more.count()&&await more.getAttribute('aria-expanded')==='false')await more.click();}



// The "Más" menu holds the rarely used actions; open it before using them.
async function openMore(page){const menu=page.locator('.editor-more');if(await menu.getAttribute('open')===null)await menu.locator('summary').click();}


