test('admin edits title, adds a picture and chooses colors by hexadecimal code',async({page})=>{await backend(page,'owner');await login(page,'owner');await editOn(page);await page.getByRole('button',{name:'Colores y temas'}).click();await page.getByRole('button',{name:'Editar paleta de colores'}).click();const drawer=page.locator('#cms-editor');await drawer.getByLabel('Código de Fondo de la app',{exact:true}).fill('#243141');await drawer.getByRole('button',{name:'Aplicar al borrador'}).click();await expect(page.locator('body')).toHaveCSS('background-color','rgb(36, 49, 65)');await page.getByRole('link',{name:'Vista previa',exact:true}).click();await editOn(page);await page.getByRole('button',{name:'Editar portada',exact:true}).first().click();await drawer.getByLabel('Título principal',{exact:true}).fill('Nuestra cocina, tus ideas');await drawer.getByRole('button',{name:'Aplicar al borrador'}).click();await expect(page.getByRole('heading',{name:'Nuestra cocina, tus ideas'})).toBeVisible();await editOn(page);await expect(page.locator('[data-layout-edit]')).not.toHaveCount(0);await page.getByRole('button',{name:'Editar elemento: Nuestra cocina, tus ideas',exact:true}).click();const picture='data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+j8ioAAAAASUVORK5CYII=';await drawer.getByLabel('Imagen del elemento',{exact:true}).fill(picture);await drawer.locator('[name="color-enabled"]').check();await drawer.getByLabel('Código de Color del texto',{exact:true}).fill('#a8dac0');await drawer.getByRole('button',{name:'Aplicar al borrador'}).click();await expect(page.locator('.hero h1 img')).toHaveAttribute('src',picture);await expect(page.locator('.hero h1')).toHaveCSS('color','rgb(168, 218, 192)');});
test('admin moves a component and returns it to its origin',async({page})=>{await backend(page,'owner');await login(page,'owner');await editOn(page);await page.getByRole('link',{name:'Vista previa',exact:true}).click();await editOn(page);await page.locator('[data-layout-key="home-welcome"]').scrollIntoViewIfNeeded();await page.getByRole('button',{name:'Mover elemento: Bienvenida',exact:true}).click();const modal=page.locator('#layout-move-dialog');const target=await modal.locator('option').evaluateAll(options=>options.find(o=>o.textContent==='Portada principal')?.value);expect(target).toBeTruthy();await modal.getByLabel('Colocar antes de').selectOption(target);await modal.getByRole('button',{name:'Mover aquí',exact:true}).click();let order=await page.locator('main>[data-layout-key]').evaluateAll(items=>items.map(e=>e.dataset.layoutKey));expect(order.indexOf('home-welcome')).toBeLessThan(order.indexOf('home-hero'));await openMore(page);await page.getByRole('button',{name:'Restaurar acomodo original'}).click();await expect(page.locator('#toast')).toHaveText('Se restauró la última versión publicada.');order=await page.locator('main>[data-layout-key]').evaluateAll(items=>items.map(e=>e.dataset.layoutKey));expect(order.indexOf('home-hero')).toBeLessThan(order.indexOf('home-welcome'));});

test('admin creates a recipe menu, documents an investigation and filters its recipes',async({page})=>{const api=await backend(page,'owner');await login(page,'owner');await editOn(page);await page.getByRole('button',{name:'Recetario',exact:true}).click();const editor=page.locator('#cms-editor');await page.getByRole('button',{name:'+ Crear menú del recetario',exact:true}).click();await editor.getByLabel('Nombre del menú',{exact:true}).fill('Aprovechamientos de prueba');await editor.getByLabel('Descripción del menú',{exact:true}).fill('Colección preparada para documentar procesos.');await editor.getByRole('button',{name:'Aplicar al borrador'}).click();await page.locator('.cms-row').filter({hasText:'Fideo seco con chicharrón de filete'}).getByRole('button',{name:'Editar',exact:true}).click();await editor.getByLabel('Aprovechamientos de prueba',{exact:true}).check();await editor.getByLabel('Aprovechamiento',{exact:true}).fill('Registro de prueba pendiente de revisión por el chef.');await editor.getByLabel('Técnica o desarrollo',{exact:true}).fill('Técnica documentada para la prueba del editor.');await editor.getByRole('button',{name:'Aplicar al borrador'}).click();await page.getByRole('link',{name:'Recetario',exact:true}).click();await page.getByRole('button',{name:/Aprovechamientos de prueba/}).click();await expect(page.locator('.dish-card')).toHaveCount(1);await expect(page.locator('.dish-card')).toContainText('Fideo seco');await page.getByRole('button',{name:'Ver ingredientes',exact:true}).click();await expect(page.locator('#detail-dialog')).toContainText('Registro de prueba pendiente');await page.getByRole('button',{name:'Cerrar detalle'}).click();await page.locator('#editor-tools').getByRole('button',{name:'Publicar',exact:true}).click();await expect(page.locator('#toast')).toHaveText('Cambios publicados para todos los visitantes.');expect(api.site.recipeMenus[0].name).toBe('Aprovechamientos de prueba');expect(api.site.recipes[0].menuIds).toEqual([api.site.recipeMenus[0].id]);});
