test('password recovery sends an explicit return URL and displays the next steps',async({page})=>{await backend(page,'visitor');await page.goto('/#recuperar');await page.getByLabel('Correo electrónico',{exact:true}).fill('PERSON@example.test');const request=page.waitForRequest(r=>new URL(r.url()).pathname==='/auth/v1/recover');await page.getByRole('button',{name:'Enviar enlace',exact:true}).click();const sent=await request;expect(sent.postDataJSON()).toEqual({email:'person@example.test'});expect(new URL(sent.url()).searchParams.get('redirect_to')).toBe('http://127.0.0.1:4173/?auth=recovery');await expect(page.locator('.account-card [role=status]')).toContainText('Solicitud enviada');await expect(page.locator('.recovery-steps')).toContainText('Escribe tu nueva contraseña dos veces');await expect(page.getByRole('button',{name:'Enviar otro enlace',exact:true})).toBeEnabled();await expect(page.getByLabel('Correo electrónico',{exact:true})).toHaveValue('person@example.test');});
test('password recovery callback without a type opens a verified reset form and saves a matching password',async({page})=>{const api=await backend(page,'visitor');await page.goto('/?auth=recovery#access_token=test-access-token&refresh_token=test-refresh-token&expires_in=3600');await expect(page.getByRole('heading',{name:'Nueva contraseña',exact:true})).toBeVisible();expect(new URL(page.url()).hash).toBe('#nueva-clave');expect(new URL(page.url()).search).toBe('');await expect(page.locator('.account-card')).toContainText('Enlace verificado');await page.getByLabel('Nueva contraseña',{exact:true}).fill('new-test-password-1234');await page.getByLabel('Confirmar nueva contraseña',{exact:true}).fill('different-test-password-1234');await page.getByRole('button',{name:'Guardar contraseña',exact:true}).click();await expect(page.locator('.form-error')).toContainText('no coinciden');expect(api.passwordUpdates).toBe(0);await page.getByLabel('Confirmar nueva contraseña',{exact:true}).fill('new-test-password-1234');await page.getByRole('button',{name:'Guardar contraseña',exact:true}).click();await expect(page.locator('.account-card [role=status]')).toContainText('Contraseña actualizada');expect(api.passwordUpdates).toBe(1);expect(new URL(page.url()).hash).toBe('#cuenta');expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);});
test('password recovery links previously sent with a recovery type still work',async({page})=>{await backend(page,'visitor');await page.goto('/#access_token=test-access-token&refresh_token=test-refresh-token&type=recovery&expires_in=3600');await expect(page.getByRole('button',{name:'Guardar contraseña',exact:true})).toBeEnabled();expect(new URL(page.url()).hash).toBe('#nueva-clave');expect(page.url()).not.toContain('test-access-token');});
test('password recovery verifies a token hash from a custom email link and removes it from the URL',async({page})=>{await backend(page,'visitor');const verify=page.waitForRequest(r=>new URL(r.url()).pathname==='/auth/v1/verify');await page.goto('/?token_hash=test-token-hash&type=recovery');expect((await verify).postDataJSON()).toEqual({token_hash:'test-token-hash',type:'recovery'});await expect(page.getByRole('button',{name:'Guardar contraseña',exact:true})).toBeEnabled();expect(new URL(page.url()).search).toBe('');expect(new URL(page.url()).hash).toBe('#nueva-clave');});
test('expired password recovery link clears a previous account and offers a new link',async({page})=>{const api=await backend(page,'owner');await login(page,'owner');await editOn(page);await page.goto('/?auth=recovery#error=access_denied&error_code=otp_expired&error_description=Expired');await expect(page.getByRole('heading',{name:'Recuperar acceso',exact:true})).toBeVisible();await expect(page.locator('.account-card [role=status]')).toContainText('caducó');await expect(page.getByRole('button',{name:'Enviar enlace',exact:true})).toBeEnabled();await expect(page.locator('#editor-tools')).toBeHidden();expect(page.url()).not.toContain('error=');expect(api.passwordUpdates).toBe(0);});
test('password reset without an authorized session explains how to get a new link',async({page})=>{const api=await backend(page,'visitor');await page.goto('/#nueva-clave');await expect(page.getByRole('link',{name:'Solicitar enlace nuevo',exact:true})).toBeVisible();await expect(page.locator('[data-account-form=reset]')).toHaveCount(0);await page.getByRole('link',{name:'Solicitar enlace nuevo',exact:true}).click();await expect(page.getByRole('button',{name:'Enviar enlace',exact:true})).toBeEnabled();expect(api.passwordUpdates).toBe(0);});
test('password recovery rejects invalid credentials before allowing a password change',async({page})=>{const api=await backend(page,'visitor');await page.route('https://*.supabase.co/auth/v1/user',route=>route.fulfill({status:401,json:{code:'bad_jwt',message:'invalid JWT'}}));await page.goto('/?auth=recovery#access_token=invalid-token&refresh_token=invalid-refresh&expires_in=3600');await expect(page.getByRole('heading',{name:'Recuperar acceso',exact:true})).toBeVisible();await expect(page.locator('.account-card [role=status]')).toContainText('ya no es válido');await expect(page.locator('[data-account-form=reset]')).toHaveCount(0);expect(api.passwordUpdates).toBe(0);expect(page.url()).not.toContain('invalid-token');});

