test('visual editor drops a component into empty page space and remains usable after drag',async({page})=>{
 await backend(page,'owner');await login(page,'owner');await editOn(page);await page.getByRole('link',{name:'Vista previa',exact:true}).click();await editOn(page);const block=page.locator('[data-layout-key="home-welcome"]');await block.scrollIntoViewIfNeeded();const cross=page.getByRole('button',{name:'Mover elemento: Bienvenida',exact:true});await expect(cross).toBeVisible();const start=await cross.boundingBox(),root=await page.locator('main').boundingBox(),x=Math.max(root.x+20,Math.min(root.x+root.width/2,page.viewportSize().width-20)),y=page.viewportSize().height/2;if(await page.evaluate(()=>navigator.maxTouchPoints>0)){const session=await page.context().newCDPSession(page),sx=start.x+start.width/2,sy=start.y+start.height/2;await session.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:sx,y:sy}]});for(let step=1;step<=12;step++)await session.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:sx+(x-sx)*step/12,y:sy+(y-sy)*step/12}]});await session.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await session.detach();}else{await page.mouse.move(start.x+start.width/2,start.y+start.height/2);await page.mouse.down();await page.mouse.move(x,y,{steps:12});await page.mouse.up();}await expect(page.locator('#toast')).toContainText('Posición libre guardada');await expect(block).toHaveCSS('position','absolute');expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await openMore(page);await page.getByRole('button',{name:'Restaurar acomodo original'}).click();await expect(block).not.toHaveCSS('position','absolute');await page.getByRole('button',{name:'Editar portada',exact:true}).first().click();await expect(page.locator('#cms-editor')).toBeVisible();
});

test('visual editor restores an older saved draft instead of silently discarding it',async({page})=>{
 await backend(page,'owner');await login(page,'owner');await editOn(page);await page.getByRole('link',{name:'Vista previa',exact:true}).click();await editOn(page);await page.getByRole('button',{name:'Editar portada',exact:true}).first().click();await page.locator('#cms-editor').getByLabel('Título principal',{exact:true}).fill('Borrador que debemos conservar');await page.locator('#cms-editor').getByRole('button',{name:'Aplicar al borrador'}).click();await expect(page.locator('.hero h1')).toHaveText('Borrador que debemos conservar');await page.evaluate(()=>new Promise((resolve,reject)=>{const request=indexedDB.open('balcon-cms-drafts',1);request.onerror=()=>reject(request.error);request.onsuccess=()=>{const db=request.result,tx=db.transaction('drafts','readwrite'),cursor=tx.objectStore('drafts').openCursor();cursor.onsuccess=()=>{const row=cursor.result;if(row){const value=row.value;delete value.document.recipeMenus;row.update(value);row.continue();}};tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>reject(tx.error);};}));await page.reload();await editOn(page);await expect(page.locator('.hero h1')).toHaveText('Borrador que debemos conservar');await expect(page.locator('#editor-tools')).toContainText('Borrador sin publicar');
});

