 await page.goto('/#cuenta');await page.locator('main').getByRole('button',{name:'Cerrar sesión',exact:true}).click();await page.getByRole('link',{name:'Nuestro libro',exact:true}).click();
 await expect(page.locator('#reader-status')).toHaveText('Página 1 de 2');await expect(page.locator('#import-book,#remove-book,#book-file')).toHaveCount(0);
