async function dragGesture(page,from,to){if(page.viewportSize().width<=820){const session=await page.context().newCDPSession(page);await session.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[from]});for(let n=1;n<=8;n++)await session.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:from.x+(to.x-from.x)*n/8,y:from.y+(to.y-from.y)*n/8}]});await session.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await session.detach();}else{await page.mouse.move(from.x,from.y);await page.mouse.down();await page.mouse.move(to.x,to.y,{steps:8});await page.mouse.up();}}

test('module frames draw, resize whole carousels and retain alignment after publishing',async({page})=>{
 const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.emulateMedia({reducedMotion:'reduce'});const api=await backend(page,'owner');await login(page,'owner');await editOn(page);await page.getByRole('link',{name:'Vista previa',exact:true}).click();await editOn(page);await page.getByRole('button',{name:'+ Agregar',exact:true}).click();const editor=page.locator('#cms-editor');await editor.getByLabel('Dibujar un cuadro para delimitar el módulo').check();await editor.getByRole('button',{name:'Carrusel',exact:true}).click();await expect(page.getByRole('dialog',{name:'Dibujar espacio del módulo'})).toBeVisible();const base=await page.locator('main').boundingBox();const from={x:base.x+8,y:260},to={x:base.x+base.width*.85,y:500};await dragGesture(page,from,to);await expect(editor).toBeVisible();await editor.getByLabel('Título',{exact:true}).fill('Carrusel delimitado');await editor.locator('[name="slides.0.imageAlign"]').selectOption('right');await editor.getByRole('button',{name:'Aplicar al borrador',exact:true}).click();const block=page.locator('.custom-block.type-carousel').last();await block.scrollIntoViewIfNeeded();await expect(block).toHaveClass(/module-framed/);expect((await block.boundingBox()).height).toBeCloseTo(240,0);await expect(block.locator('[data-carousel-slide]').first()).toHaveClass(/image-right/);await selectModule(page,block);const key=await block.getAttribute('data-edit-key');await expandTool(page);await press(page.locator(`[data-layout-frame="${key}"]`),page);const corner=page.locator('[data-module-corner="se"]');await expect(corner).toBeVisible();const r=await corner.boundingBox();await dragGesture(page,{x:r.x+r.width/2,y:r.y+r.height/2},{x:r.x+r.width/2-35,y:r.y+r.height/2+40});await expect(page.locator('#toast')).toHaveText('Tamaño del módulo aplicado sin separar su contenido.');let resized=await block.boundingBox();expect(resized.height).toBeGreaterThan(265);await press(page.locator(`[data-layout-edit="${key}"]`),page);await editor.getByLabel('Alto del módulo (px, avanzado: déjalo vacío para escalar proporcionalmente)',{exact:true}).fill('360');await editor.getByRole('button',{name:'Aplicar al borrador',exact:true}).click();resized=await block.boundingBox();expect(resized.height).toBe(360);await publishDraft(page);expect(api.site.sectionBlocks.noticias.at(-1).moduleHeight).toBeGreaterThan(265);await page.reload();await editOn(page);await expect(block).toHaveClass(/module-framed/);expect((await block.boundingBox()).height).toBeCloseTo(resized.height,0);expect(errors).toEqual([]);
});

